package dev.legible.storage;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/**
 * Loads the runtime schema descriptor generated by {@code quality-gate/rmap.py}.
 *
 * <p>The descriptor is an internal build artifact. Conceptual-model validation
 * and Rmap derivation happen outside Java; the runtime only consumes the
 * derived tables, columns, keys, checks, and predicate→column mapping.
 */
public final class RmapSchemaLoader {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private RmapSchemaLoader() {
    }

    public static List<RelationSchema> load(Path path) {
        try (InputStream in = Files.newInputStream(path)) {
            return load(in);
        } catch (IOException e) {
            throw new IllegalStateException(
                    "cannot read generated schema descriptor " + path, e);
        }
    }

    public static List<RelationSchema> load(InputStream in) {
        try {
            JsonNode root = MAPPER.readTree(in);
            List<RelationSchema> schemas = new ArrayList<>();
            for (JsonNode model : root.path("models")) {
                for (JsonNode table : model.path("tables")) {
                    schemas.add(toSchema(table));
                }
            }
            return schemas;
        } catch (IOException e) {
            throw new IllegalStateException(
                    "cannot parse generated schema descriptor", e);
        }
    }

    private static RelationSchema toSchema(JsonNode table) {
        List<RelationSchema.Column> columns = new ArrayList<>();
        for (JsonNode column : table.path("columns")) {
            columns.add(new RelationSchema.Column(
                    text(column, "predicate"),
                    text(column, "column"),
                    text(column, "sqlType"),
                    column.path("mandatory").asBoolean(false),
                    column.path("unique").asBoolean(false),
                    nullableText(column, "default"),
                    nullableText(column, "valueConstraint"),
                    nullableText(column, "uniqueWhileAbsent")));
        }
        List<RelationSchema.Check> checks = new ArrayList<>();
        for (JsonNode check : table.path("checks")) {
            checks.add(new RelationSchema.Check(
                    text(check, "name"), text(check, "expression")));
        }
        return new RelationSchema(
                text(table, "concept"),
                text(table, "table"),
                text(table, "objectType"),
                columns,
                strings(table.path("primaryKey")),
                strings(table.path("foreignKeys")),
                checks,
                false,
                text(table, "ddl"));
    }

    private static List<String> strings(JsonNode array) {
        List<String> values = new ArrayList<>();
        for (JsonNode item : array) {
            values.add(item.asText());
        }
        return values;
    }

    private static String text(JsonNode node, String field) {
        return node.path(field).asText();
    }

    private static String nullableText(JsonNode node, String field) {
        JsonNode value = node.path(field);
        return value.isMissingNode() || value.isNull() ? null : value.asText();
    }
}
